// Memory on the device (OpenSpec change assistant-memory, tasks 2.1, 2.2):
// memory.vectors.json is generated by `go test ./internal/assistant -run Device
// -update` from PlanRemember, and a turn sends the live items and plans remember.
import 'fake-indexeddb/auto'
import { beforeEach, describe, expect, it } from 'vitest'
import { db, useDatabase } from '../db'
import { MAX_MEMORY_ITEMS, MAX_MEMORY_TEXT } from '../memory'
import { setCurrentUserId } from '../sharing'
import type { ProposedChange, TurnEvent } from '../assistantTypes'
import type { MemoryItem } from '../types'
import { manifest } from './manifest'
import { runDeviceTurn } from './loop'
import { planRemember } from './memory'
import type { Provider, Request, Round, ToolResult } from './providers'
import vectors from './memory.vectors.json'

let n = 0
beforeEach(async () => {
  useDatabase(`device-memory-${Date.now()}-${n++}`)
  await setCurrentUserId('u1')
})

const row = (id: string, text: string, position: number, deleted_at: number | null = null): MemoryItem => ({ id, text, position, created_at: 1, deleted_at, _clock: {} })

describe('remember vectors', () => {
  for (const c of vectors as { name: string; live: string[]; draft?: string[]; args: unknown; error?: string; text?: string }[]) {
    it(c.name, () => {
      const draft: ProposedChange[] = (c.draft ?? []).map((text, i) => ({ entity: 'memory', entityId: `d${i}`, create: true, patch: { text } }))
      const plan = planRemember(c.live, draft, c.args, 'id', 1)
      if (c.error) expect(plan.result.error).toBe(c.error)
      else expect([plan.result.text, plan.change?.patch.text]).toEqual([c.text, c.text])
    })
  }
})

it('keeps the limits of the server', () => {
  expect([manifest.memory.max_items, manifest.memory.max_text]).toEqual([MAX_MEMORY_ITEMS, MAX_MEMORY_TEXT])
})

function fake(rounds: Partial<Round>[]) {
  const seen: { req?: Request; results: ToolResult[][]; later?: string[] } = { results: [] }
  const provider: Provider = {
    start(req) {
      seen.req = req
      let i = 0
      return {
        async next() { return { stop: 'end_turn', rawStop: '', toolCalls: [], input: 1, output: 1, ...rounds[i++] } },
        addToolResults(results) { seen.results.push(results) },
        setTools(list) { seen.later = list.map((t) => t.name) },
      }
    },
  }
  return { provider, seen }
}

it('sends the live items in order and plans remember without writing', async () => {
  await db.memories.bulkPut([row('m2', 'Mornings are for deep work', 2), row('m1', 'Anna is my manager', 1), row('gone', 'Old fact', 0, 5), row('x', '[Cannot decrypt]', 3)])
  const { provider, seen } = fake([
    { stop: 'tool_use', toolCalls: [{ id: 'p', name: 'propose_changes', args: '{}' }] },
    { stop: 'tool_use', toolCalls: [{ id: 'c1', name: 'remember', args: '{"text":"Does not work on Fridays"}' }] },
    { stop: 'end_turn' },
  ])
  const events: TurnEvent[] = []
  await runDeviceTurn({ messages: [{ role: 'user', text: "I don't work on Fridays" }], timezone: 'UTC' }, (e) => events.push(e), undefined,
    { setup: { provider: 'anthropic', model: 'm', key: 'k', savedAt: 1 }, userName: 'Ada', provider, now: () => 5 })
  expect(seen.req!.system).toContain(`\n\n${manifest.memory.note}\n- Anna is my manager\n- Mornings are for deep work\n`)
  expect(seen.req!.system).not.toContain('Old fact')
  expect(seen.req!.system).not.toContain('Cannot decrypt')
  // remember is a write: offered after propose_changes (assistant-lean-tools D1).
  expect(seen.req!.tools.map((t) => t.name)).not.toContain('remember')
  expect(seen.later).toContain('remember')
  const cs = events.find((e) => e.type === 'changeset') as Extract<TurnEvent, { type: 'changeset' }>
  expect(cs.items).toEqual([expect.objectContaining({ entity: 'memory', create: true, patch: { text: 'Does not work on Fridays', position: 5, created_at: 5 } })])
  expect(await db.memories.count()).toBe(4)
})

it('offers no remember to a skill', async () => {
  const { provider, seen } = fake([
    { stop: 'tool_use', toolCalls: [{ id: 'c1', name: 'remember', args: '{"text":"Likes tea"}' }] },
    { stop: 'end_turn' },
  ])
  await runDeviceTurn({ messages: [{ role: 'user', text: 'plan' }], timezone: 'UTC', skill: 'plan-week' }, () => undefined, undefined,
    { setup: { provider: 'anthropic', model: 'm', key: 'k', savedAt: 1 }, userName: 'Ada', provider, now: () => 5 })
  expect(seen.req!.tools.map((t) => t.name)).not.toContain('remember')
  expect(seen.results[0][0]).toMatchObject({ isError: true })
})
